tool_schemas.implementation:
def zotero_search_items(library_id, query, item_type=None, collection_id=None, tag=None, has_fulltext=None, include_deleted=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_operation(lib_id, op_type, request_params, status, result_summary=None, error_code=None, error_message=None):
        ops = _load("operations.json")
        # rate limit: operations created per minute per library (simple hard limit)
        # Use 60/min default; if exceeded, force failed with RATE_LIMITED per business rules.
        minute_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in ops:
            if r.get("library_id") == lib_id and isinstance(r.get("created_at"), str) and r["created_at"] >= minute_ago:
                recent += 1
        if recent >= 60:
            status = "failed"
            error_code = "RATE_LIMITED"
            error_message = "Rate limit exceeded for this library"
            result_summary = None

        def _new_id(prefix):
            # ULID-like, but deterministic enough offline: 26 chars Crockford base32 from sha1(time+rand)
            alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
            raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
            digest = hashlib.sha1(raw).digest()
            # 130 bits -> 26 base32 chars (5 bits each)
            bits = int.from_bytes(digest[:17], "big")  # 136 bits
            chars = []
            for _ in range(26):
                chars.append(alphabet[bits & 31])
                bits >>= 5
            return prefix + "_" + "".join(reversed(chars))

        op = {
            "id": _new_id("zop"),
            "library_id": lib_id,
            "op_type": op_type,
            "request_params_json": request_params if isinstance(request_params, dict) else {},
            "status": "succeeded" if status == "succeeded" else "failed" if status == "failed" else status,
            "result_summary_json": result_summary,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now
        }
        ops.append(op)
        _save("operations.json", ops)
        return op

    # Validate inputs
    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        _record_operation(library_id if isinstance(library_id, str) else "unknown", "search_items",
                          {"library_id": library_id, "query": query}, "failed",
                          error_code="VALIDATION_ERROR", error_message="library_id must be a zlib_* ULID")
        return _err("VALIDATION_ERROR", "library_id must be a zlib_* ULID")
    if not isinstance(query, str) or query.strip() == "":
        _record_operation(library_id, "search_items", {"library_id": library_id, "query": query}, "failed",
                          error_code="VALIDATION_ERROR", error_message="query is required")
        return _err("VALIDATION_ERROR", "query is required")
    if item_type is not None:
        if not isinstance(item_type, str) or item_type not in ("bibliographic", "attachment", "note", "annotation", "other"):
            _record_operation(library_id, "search_items", {"library_id": library_id, "query": query, "item_type": item_type}, "failed",
                              error_code="VALIDATION_ERROR", error_message="invalid item_type")
            return _err("VALIDATION_ERROR", "invalid item_type")
    if collection_id is not None:
        if not isinstance(collection_id, str) or not re.match(r"^zcol_[0-9A-HJKMNP-TV-Z]{26}$", collection_id):
            _record_operation(library_id, "search_items", {"library_id": library_id, "query": query, "collection_id": collection_id}, "failed",
                              error_code="VALIDATION_ERROR", error_message="collection_id must be a zcol_* ULID")
            return _err("VALIDATION_ERROR", "collection_id must be a zcol_* ULID")
    if tag is not None and not isinstance(tag, str):
        _record_operation(library_id, "search_items", {"library_id": library_id, "query": query, "tag": tag}, "failed",
                          error_code="VALIDATION_ERROR", error_message="tag must be a string")
        return _err("VALIDATION_ERROR", "tag must be a string")
    if has_fulltext is not None and not isinstance(has_fulltext, bool):
        _record_operation(library_id, "search_items", {"library_id": library_id, "query": query, "has_fulltext": has_fulltext}, "failed",
                          error_code="VALIDATION_ERROR", error_message="has_fulltext must be boolean")
        return _err("VALIDATION_ERROR", "has_fulltext must be boolean")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _record_operation(library_id, "search_items", {"library_id": library_id, "query": query, "include_deleted": include_deleted}, "failed",
                          error_code="VALIDATION_ERROR", error_message="include_deleted must be boolean")
        return _err("VALIDATION_ERROR", "include_deleted must be boolean")
    if sort is not None:
        if not isinstance(sort, str) or sort not in ("relevance", "title", "date", "created_at", "updated_at"):
            _record_operation(library_id, "search_items", {"library_id": library_id, "query": query, "sort": sort}, "failed",
                              error_code="VALIDATION_ERROR", error_message="invalid sort")
            return _err("VALIDATION_ERROR", "invalid sort")
    if order is not None:
        if not isinstance(order, str) or order not in ("asc", "desc"):
            _record_operation(library_id, "search_items", {"library_id": library_id, "query": query, "order": order}, "failed",
                              error_code="VALIDATION_ERROR", error_message="invalid order")
            return _err("VALIDATION_ERROR", "invalid order")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _record_operation(library_id, "search_items", {"library_id": library_id, "query": query, "limit": limit}, "failed",
                              error_code="VALIDATION_ERROR", error_message="limit must be 1-200")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    else:
        limit = 50

    if cursor is not None and not isinstance(cursor, str):
        _record_operation(library_id, "search_items", {"library_id": library_id, "query": query, "cursor": cursor}, "failed",
                          error_code="VALIDATION_ERROR", error_message="cursor must be a string")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    libs = _load("libraries.json")
    lib = next((l for l in libs if l.get("id") == library_id), None)
    if not lib:
        _record_operation(library_id, "search_items", {"library_id": library_id, "query": query}, "failed",
                          error_code="NOT_FOUND", error_message="library not found")
        return _err("NOT_FOUND", "library not found")
    if lib.get("status") in ("revoked",):
        _record_operation(library_id, "search_items", {"library_id": library_id, "query": query}, "failed",
                          error_code="UNAUTHORIZED", error_message="library access revoked")
        return _err("UNAUTHORIZED", "You do not have access to this library")

    items = _load("items.json")
    collections = _load("collections.json")
    item_cols = _load("item_collections.json")
    tags_rows = _load("tags.json")

    # Collection scope validation + membership set
    scoped_item_ids = None
    if collection_id is not None:
        col = next((c for c in collections if c.get("id") == collection_id), None)
        if not col or col.get("library_id") != library_id:
            _record_operation(library_id, "search_items",
                              {"library_id": library_id, "query": query, "collection_id": collection_id},
                              "failed", error_code="NOT_FOUND", error_message="collection not found")
            return _err("NOT_FOUND", "collection not found")
        scoped_item_ids = set()
        for ic in item_cols:
            if ic.get("collection_id") == collection_id and ic.get("status") == "active":
                if ic.get("library_id") != library_id:
                    _record_operation(library_id, "search_items",
                                      {"library_id": library_id, "query": query, "collection_id": collection_id},
                                      "failed", error_code="VALIDATION_ERROR", error_message="cross-library join rejected")
                    return _err("VALIDATION_ERROR", "cross-library join rejected")
                scoped_item_ids.add(ic.get("item_id"))

    # Tag scope: set of item_ids with active assignment to a tag name
    scoped_by_tag_ids = None
    if tag is not None:
        scoped_by_tag_ids = set()
        # Find tag row by exact name
        tag_row = next((t for t in tags_rows if t.get("library_id") == library_id and t.get("name") == tag), None)
        if tag_row:
            for it in tag_row.get("item_tags", []) or []:
                if it.get("status") == "active":
                    scoped_by_tag_ids.add(it.get("item_id"))
        else:
            # No matching tag => empty results (not error)
            scoped_by_tag_ids = set()

    # Determine defaults: exclude attachment/annotation unless explicitly included by server defaults
    # Here: exclude unless caller explicitly set item_type to those. If item_type is None, exclude both.
    exclude_types = set()
    if item_type is None:
        exclude_types = {"attachment", "annotation"}

    q = query.strip().lower()
    terms = [t for t in re.split(r"\s+", q) if t]

    def _field_text(it):
        parts = []
        for k in ("title", "date", "publication_title", "doi", "url", "abstract_note", "note_html", "fulltext_text"):
            v = it.get(k)
            if isinstance(v, str) and v:
                parts.append(v)
        creators = it.get("creators")
        if isinstance(creators, list):
            for c in creators:
                if isinstance(c, dict):
                    for ck in ("firstName", "lastName", "name"):
                        cv = c.get(ck)
                        if isinstance(cv, str) and cv:
                            parts.append(cv)
        mj = it.get("metadata_json")
        if isinstance(mj, dict):
            try:
                parts.append(json.dumps(mj, ensure_ascii=False))
            except Exception:
                pass
        return " ".join(parts).lower()

    def _score(it_text):
        # simple relevance: count term occurrences
        score = 0
        for t in terms:
            if not t:
                continue
            # count non-overlapping occurrences
            score += it_text.count(t)
        return score

    filtered = []
    for it in items:
        if it.get("library_id") != library_id:
            continue

        st = it.get("status")
        if include_deleted:
            pass
        else:
            if st != "active":
                continue

        if item_type is not None and it.get("item_type") != item_type:
            continue
        if item_type is None and it.get("item_type") in exclude_types:
            continue

        if has_fulltext is True:
            if not isinstance(it.get("fulltext_text"), str) or it.get("fulltext_text", "").strip() == "":
                continue

        if scoped_item_ids is not None:
            if it.get("id") not in scoped_item_ids:
                continue

        if scoped_by_tag_ids is not None:
            if it.get("id") not in scoped_by_tag_ids:
                continue

        it_text = _field_text(it)
        if not terms:
            rel = 0
        else:
            rel = _score(it_text)
        if rel <= 0 and terms:
            continue
        filtered.append((it, rel))

    # Sorting
    sort = sort or "relevance"
    order = order or "desc"

    def _safe_dt(s):
        return s if isinstance(s, str) else ""

    if sort == "relevance":
        keyfn = lambda pair: (pair[1], _safe_dt(pair[0].get("updated_at")), pair[0].get("id", ""))
    elif sort == "title":
        keyfn = lambda pair: ((pair[0].get("title") or "").lower(), pair[0].get("id", ""))
    elif sort == "date":
        keyfn = lambda pair: ((pair[0].get("date") or "").lower(), pair[0].get("id", ""))
    elif sort == "created_at":
        keyfn = lambda pair: (_safe_dt(pair[0].get("created_at")), pair[0].get("id", ""))
    elif sort == "updated_at":
        keyfn = lambda pair: (_safe_dt(pair[0].get("updated_at")), pair[0].get("id", ""))
    else:
        keyfn = lambda pair: (pair[1], pair[0].get("id", ""))

    reverse = (order == "desc")
    filtered.sort(key=keyfn, reverse=reverse)

    # Pagination via cursor encoding offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            payload = json.loads(raw)
            if payload.get("library_id") != library_id:
                _record_operation(library_id, "search_items",
                                  {"library_id": library_id, "query": query, "cursor": cursor},
                                  "failed", error_code="VALIDATION_ERROR", error_message="cursor does not match library")
                return _err("VALIDATION_ERROR", "cursor does not match library")
            if payload.get("op") != "zotero_search_items":
                _record_operation(library_id, "search_items",
                                  {"library_id": library_id, "query": query, "cursor": cursor},
                                  "failed", error_code="VALIDATION_ERROR", error_message="invalid cursor")
                return _err("VALIDATION_ERROR", "invalid cursor")
            offset = int(payload.get("offset", 0))
            if offset < 0:
                offset = 0
        except Exception:
            _record_operation(library_id, "search_items",
                              {"library_id": library_id, "query": query, "cursor": cursor},
                              "failed", error_code="VALIDATION_ERROR", error_message="invalid cursor")
            return _err("VALIDATION_ERROR", "invalid cursor")

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {"op": "zotero_search_items", "library_id": library_id, "offset": next_offset}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload).encode("utf-8")).decode("utf-8").rstrip("=")

    # Response rows: do not fabricate; return actual item rows (lightly)
    out_items = []
    for it, rel in page:
        out = dict(it)
        if sort == "relevance":
            out["_relevance"] = rel
        out_items.append(out)

    op = _record_operation(
        library_id,
        "search_items",
        {
            "library_id": library_id,
            "query": query,
            "item_type": item_type,
            "collection_id": collection_id,
            "tag": tag,
            "has_fulltext": has_fulltext,
            "include_deleted": include_deleted,
            "sort": sort,
            "order": order,
            "limit": limit,
            "cursor": cursor
        },
        "succeeded",
        result_summary={"returned": len(out_items), "total": total, "has_more": has_more}
    )

    return {
        "operation_id": op.get("id"),
        "items": out_items,
        "page": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        },
        "sort": {"by": sort, "order": order},
        "latency_ms": int((time.time() - t0) * 1000)
    }

def zotero_get_item_metadata(library_id, item_key, include_children=None, include_collections=None, include_tags=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_operation(lib_id, status, result_summary=None, error_code=None, error_message=None, request_params=None):
        ops = _load("operations.json")
        minute_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = sum(1 for r in ops if r.get("library_id") == lib_id and isinstance(r.get("created_at"), str) and r["created_at"] >= minute_ago)
        if recent >= 60:
            status = "failed"
            error_code = "RATE_LIMITED"
            error_message = "Rate limit exceeded for this library"
            result_summary = None

        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        digest = hashlib.sha1(raw).digest()
        bits = int.from_bytes(digest[:17], "big")
        chars = []
        for _ in range(26):
            chars.append(alphabet[bits & 31])
            bits >>= 5
        op_id = "zop_" + "".join(reversed(chars))

        op = {
            "id": op_id,
            "library_id": lib_id,
            "op_type": "get_item_metadata",
            "request_params_json": request_params if isinstance(request_params, dict) else {},
            "status": "succeeded" if status == "succeeded" else "failed" if status == "failed" else status,
            "result_summary_json": result_summary,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now
        }
        ops.append(op)
        _save("operations.json", ops)
        return op

    # Validate
    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        _record_operation(library_id if isinstance(library_id, str) else "unknown", "failed",
                          error_code="VALIDATION_ERROR", error_message="library_id must be a zlib_* ULID",
                          request_params={"library_id": library_id, "item_key": item_key})
        return _err("VALIDATION_ERROR", "library_id must be a zlib_* ULID")
    if not isinstance(item_key, str) or item_key.strip() == "":
        _record_operation(library_id, "failed",
                          error_code="VALIDATION_ERROR", error_message="item_key is required",
                          request_params={"library_id": library_id, "item_key": item_key})
        return _err("VALIDATION_ERROR", "item_key is required")
    for nm, v in (("include_children", include_children), ("include_collections", include_collections), ("include_tags", include_tags)):
        if v is not None and not isinstance(v, bool):
            _record_operation(library_id, "failed",
                              error_code="VALIDATION_ERROR", error_message=f"{nm} must be boolean",
                              request_params={"library_id": library_id, "item_key": item_key, nm: v})
            return _err("VALIDATION_ERROR", f"{nm} must be boolean")

    libs = _load("libraries.json")
    lib = next((l for l in libs if l.get("id") == library_id), None)
    if not lib:
        _record_operation(library_id, "failed",
                          error_code="NOT_FOUND", error_message="library not found",
                          request_params={"library_id": library_id, "item_key": item_key})
        return _err("NOT_FOUND", "library not found")
    if lib.get("status") in ("revoked",):
        _record_operation(library_id, "failed",
                          error_code="UNAUTHORIZED", error_message="library access revoked",
                          request_params={"library_id": library_id, "item_key": item_key})
        return _err("UNAUTHORIZED", "You do not have access to this library")

    items = _load("items.json")
    it = next((r for r in items if r.get("library_id") == library_id and r.get("zotero_key") == item_key), None)
    if not it or it.get("status") == "deleted":
        _record_operation(library_id, "failed",
                          error_code="NOT_FOUND", error_message="item not found",
                          request_params={"library_id": library_id, "item_key": item_key})
        return _err("NOT_FOUND", "item not found")

    resp = {"item": dict(it)}

    if include_children:
        # children must be active and same library; grouped by item_type
        groups = {"attachment": [], "note": [], "annotation": [], "other": []}
        for ch in items:
            if ch.get("library_id") != library_id:
                continue
            if ch.get("status") != "active":
                continue
            if ch.get("parent_item_id") == it.get("id"):
                tp = ch.get("item_type") if ch.get("item_type") in groups else "other"
                groups[tp].append({
                    "id": ch.get("id"),
                    "zotero_key": ch.get("zotero_key"),
                    "item_type": ch.get("item_type"),
                    "title": ch.get("title"),
                    "created_at": ch.get("created_at"),
                    "updated_at": ch.get("updated_at")
                })
        resp["children"] = groups

    if include_collections:
        collections = _load("collections.json")
        item_cols = _load("item_collections.json")
        col_by_id = {c.get("id"): c for c in collections if c.get("library_id") == library_id}
        cols = []
        for ic in item_cols:
            if ic.get("library_id") != library_id:
                continue
            if ic.get("item_id") != it.get("id"):
                continue
            if ic.get("status") != "active":
                continue
            c = col_by_id.get(ic.get("collection_id"))
            if not c:
                # integrity issue; reject cross-library join if detected
                other = next((cc for cc in collections if cc.get("id") == ic.get("collection_id")), None)
                if other and other.get("library_id") != library_id:
                    op = _record_operation(library_id, "failed",
                                           error_code="VALIDATION_ERROR", error_message="cross-library join rejected",
                                           request_params={"library_id": library_id, "item_key": item_key, "include_collections": True})
                    return _err("VALIDATION_ERROR", "cross-library join rejected")
                continue
            cols.append({"id": c.get("id"), "zotero_key": c.get("zotero_key"), "name": c.get("name"), "parent_collection_id": c.get("parent_collection_id")})
        resp["collections"] = cols

    if include_tags:
        tags_rows = _load("tags.json")
        tags_out = []
        for tr in tags_rows:
            if tr.get("library_id") != library_id:
                continue
            for itag in (tr.get("item_tags") or []):
                if itag.get("status") == "active" and itag.get("item_id") == it.get("id") and itag.get("tag_id") == tr.get("id"):
                    tags_out.append({"id": tr.get("id"), "name": tr.get("name"), "color": tr.get("color")})
                    break
        resp["tags"] = tags_out

    op = _record_operation(
        library_id,
        "succeeded",
        result_summary={"item_id": it.get("id"), "zotero_key": it.get("zotero_key")},
        request_params={
            "library_id": library_id,
            "item_key": item_key,
            "include_children": include_children,
            "include_collections": include_collections,
            "include_tags": include_tags
        }
    )
    resp["operation_id"] = op.get("id")
    resp["latency_ms"] = int((time.time() - t0) * 1000)
    return resp

def zotero_get_collections(library_id, include_deleted=None, parent_collection_id=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_operation(lib_id, status, result_summary=None, error_code=None, error_message=None, request_params=None):
        ops = _load("operations.json")
        minute_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = sum(1 for r in ops if r.get("library_id") == lib_id and isinstance(r.get("created_at"), str) and r["created_at"] >= minute_ago)
        if recent >= 60:
            status = "failed"
            error_code = "RATE_LIMITED"
            error_message = "Rate limit exceeded for this library"
            result_summary = None

        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        digest = hashlib.sha1(raw).digest()
        bits = int.from_bytes(digest[:17], "big")
        chars = []
        for _ in range(26):
            chars.append(alphabet[bits & 31])
            bits >>= 5
        op_id = "zop_" + "".join(reversed(chars))

        op = {
            "id": op_id,
            "library_id": lib_id,
            "op_type": "get_collections",
            "request_params_json": request_params if isinstance(request_params, dict) else {},
            "status": "succeeded" if status == "succeeded" else "failed" if status == "failed" else status,
            "result_summary_json": result_summary,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now
        }
        ops.append(op)
        _save("operations.json", ops)
        return op

    # Validate
    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        _record_operation(library_id if isinstance(library_id, str) else "unknown", "failed",
                          error_code="VALIDATION_ERROR", error_message="library_id must be a zlib_* ULID",
                          request_params={"library_id": library_id})
        return _err("VALIDATION_ERROR", "library_id must be a zlib_* ULID")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _record_operation(library_id, "failed",
                          error_code="VALIDATION_ERROR", error_message="include_deleted must be boolean",
                          request_params={"library_id": library_id, "include_deleted": include_deleted})
        return _err("VALIDATION_ERROR", "include_deleted must be boolean")
    if parent_collection_id is not None:
        if not isinstance(parent_collection_id, str) or not re.match(r"^zcol_[0-9A-HJKMNP-TV-Z]{26}$", parent_collection_id):
            _record_operation(library_id, "failed",
                              error_code="VALIDATION_ERROR", error_message="parent_collection_id must be a zcol_* ULID",
                              request_params={"library_id": library_id, "parent_collection_id": parent_collection_id})
            return _err("VALIDATION_ERROR", "parent_collection_id must be a zcol_* ULID")
    if sort is not None:
        if not isinstance(sort, str) or sort not in ("name", "created_at", "updated_at"):
            _record_operation(library_id, "failed",
                              error_code="VALIDATION_ERROR", error_message="invalid sort",
                              request_params={"library_id": library_id, "sort": sort})
            return _err("VALIDATION_ERROR", "invalid sort")
    if order is not None:
        if not isinstance(order, str) or order not in ("asc", "desc"):
            _record_operation(library_id, "failed",
                              error_code="VALIDATION_ERROR", error_message="invalid order",
                              request_params={"library_id": library_id, "order": order})
            return _err("VALIDATION_ERROR", "invalid order")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            _record_operation(library_id, "failed",
                              error_code="VALIDATION_ERROR", error_message="limit must be 1-500",
                              request_params={"library_id": library_id, "limit": limit})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 500")
    else:
        limit = 200
    if cursor is not None and not isinstance(cursor, str):
        _record_operation(library_id, "failed",
                          error_code="VALIDATION_ERROR", error_message="cursor must be a string",
                          request_params={"library_id": library_id, "cursor": cursor})
        return _err("VALIDATION_ERROR", "cursor must be a string")

    libs = _load("libraries.json")
    lib = next((l for l in libs if l.get("id") == library_id), None)
    if not lib:
        _record_operation(library_id, "failed",
                          error_code="NOT_FOUND", error_message="library not found",
                          request_params={"library_id": library_id})
        return _err("NOT_FOUND", "library not found")
    if lib.get("status") in ("revoked",):
        _record_operation(library_id, "failed",
                          error_code="UNAUTHORIZED", error_message="library access revoked",
                          request_params={"library_id": library_id})
        return _err("UNAUTHORIZED", "You do not have access to this library")

    cols = _load("collections.json")

    # parent_collection_id must reference a collection in same library (if provided)
    if parent_collection_id is not None:
        parent = next((c for c in cols if c.get("id") == parent_collection_id), None)
        if not parent or parent.get("library_id") != library_id:
            _record_operation(library_id, "failed",
                              error_code="NOT_FOUND", error_message="parent collection not found",
                              request_params={"library_id": library_id, "parent_collection_id": parent_collection_id})
            return _err("NOT_FOUND", "parent collection not found")

    # Filter
    filtered = []
    for c in cols:
        if c.get("library_id") != library_id:
            continue
        if not include_deleted and c.get("status") != "active":
            continue
        if parent_collection_id is not None:
            if c.get("parent_collection_id") != parent_collection_id:
                continue
        filtered.append(c)

    # Sort
    sort = sort or "name"
    order = order or "asc"
    reverse = (order == "desc")

    def _safe_dt(s):
        return s if isinstance(s, str) else ""

    if sort == "name":
        filtered.sort(key=lambda r: ((r.get("name") or "").lower(), r.get("id", "")), reverse=reverse)
    elif sort == "created_at":
        filtered.sort(key=lambda r: (_safe_dt(r.get("created_at")), r.get("id", "")), reverse=reverse)
    elif sort == "updated_at":
        filtered.sort(key=lambda r: (_safe_dt(r.get("updated_at")), r.get("id", "")), reverse=reverse)

    # Cursor pagination by offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            payload = json.loads(raw)
            if payload.get("library_id") != library_id or payload.get("op") != "zotero_get_collections":
                _record_operation(library_id, "failed",
                                  error_code="VALIDATION_ERROR", error_message="invalid cursor",
                                  request_params={"library_id": library_id, "cursor": cursor})
                return _err("VALIDATION_ERROR", "invalid cursor")
            offset = int(payload.get("offset", 0))
            if offset < 0:
                offset = 0
        except Exception:
            _record_operation(library_id, "failed",
                              error_code="VALIDATION_ERROR", error_message="invalid cursor",
                              request_params={"library_id": library_id, "cursor": cursor})
            return _err("VALIDATION_ERROR", "invalid cursor")

    total = len(filtered)
    page_rows = filtered[offset: offset + limit]
    next_offset = offset + len(page_rows)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {"op": "zotero_get_collections", "library_id": library_id, "offset": next_offset}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload).encode("utf-8")).decode("utf-8").rstrip("=")

    op = _record_operation(
        library_id,
        "succeeded",
        result_summary={"returned": len(page_rows), "total": total, "has_more": has_more},
        request_params={
            "library_id": library_id,
            "include_deleted": include_deleted,
            "parent_collection_id": parent_collection_id,
            "sort": sort,
            "order": order,
            "limit": limit,
            "cursor": cursor
        }
    )

    return {
        "operation_id": op.get("id"),
        "collections": [dict(r) for r in page_rows],
        "page": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        },
        "sort": {"by": sort, "order": order},
        "latency_ms": int((time.time() - t0) * 1000)
    }

def zotero_get_collection_items(library_id, collection_key, include_deleted=None, item_type=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v.astimezone(datetime.timezone.utc)
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                else:
                    dt = dt.astimezone(datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[ms & 31])
            ms >>= 5
        time_part = "".join(reversed(chars))
        rand_part = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{time_part}{rand_part}"

    def _record_op(status, params, result_summary=None, error_code=None, error_message=None):
        ops = _load("operations.json")
        if not isinstance(ops, list):
            ops = []
        now = _iso_now()
        row = {
            "id": _new_ulid("zop"),
            "library_id": library_id if isinstance(library_id, str) else "unknown",
            "op_type": "get_collection_items",
            "request_params_json": params if isinstance(params, dict) else {},
            "status": status,
            "result_summary_json": result_summary,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("operations.json", ops)
        return row

    def _rate_limit_allow(lib_id):
        # conservative default: 60 operations/minute per library
        ops = _load("operations.json")
        if not isinstance(ops, list):
            return True, None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in ops:
            if r.get("library_id") != lib_id:
                continue
            ca = _parse_dt_any(r.get("created_at"))
            if ca and ca >= window_start:
                cnt += 1
        if cnt >= 60:
            retry_after = 60 - int((now_dt - window_start).total_seconds())
            if retry_after < 1:
                retry_after = 1
            return False, retry_after
        return True, None

    # Validate
    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="library_id must be a zlib_* ULID.")
        return _err("VALIDATION_ERROR", "library_id must be a zlib_* ULID.", operation_id=op["id"])
    if not isinstance(collection_key, str) or not collection_key.strip():
        op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="collection_key is required.")
        return _err("VALIDATION_ERROR", "collection_key is required.", operation_id=op["id"])
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="include_deleted must be a boolean.")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean.", operation_id=op["id"])
    if item_type is not None and item_type not in ("bibliographic", "attachment", "note", "annotation", "other"):
        op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="item_type invalid.")
        return _err("VALIDATION_ERROR", "item_type must be one of: bibliographic, attachment, note, annotation, other.", operation_id=op["id"])
    if sort is None:
        sort = "title"
    if sort not in ("title", "date", "created_at", "updated_at"):
        op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="sort invalid.")
        return _err("VALIDATION_ERROR", "sort must be one of: title, date, created_at, updated_at.", operation_id=op["id"])
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="order invalid.")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.", operation_id=op["id"])
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="limit out of range.")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", operation_id=op["id"])
    if cursor is not None and not isinstance(cursor, str):
        op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="cursor must be a string.")
        return _err("VALIDATION_ERROR", "cursor must be a string.", operation_id=op["id"])

    ok, retry_after = _rate_limit_allow(library_id)
    if not ok:
        op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                        error_code="RATE_LIMITED", error_message=f"Too many operations created for this library in the last minute; retry after {retry_after}s.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=retry_after, operation_id=op["id"])

    libraries = _load("libraries.json")
    if not isinstance(libraries, list):
        libraries = []
    lib = next((r for r in libraries if r.get("id") == library_id), None)
    if not lib:
        op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                        error_code="NOT_FOUND", error_message="Library not found.")
        return _err("NOT_FOUND", "Library not found.", operation_id=op["id"])

    # Resolve collection by key. If not found in this library, return empty set (read tools do not error on empty matches).
    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []
    col = next((c for c in collections if c.get("library_id") == library_id and c.get("zotero_key") == collection_key and c.get("status") == "active"), None)

    item_collections = _load("item_collections.json")
    if not isinstance(item_collections, list):
        item_collections = []
    items = _load("items.json")
    if not isinstance(items, list):
        items = []

    # Cursor: "field:ISO"
    after_dt = None
    after_field = None
    if cursor:
        if ":" not in cursor:
            op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message="cursor is malformed.")
            return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op["id"])
        after_field, after_val = cursor.split(":", 1)
        if after_field not in ("created_at", "updated_at", "date", "title"):
            op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message="cursor field invalid.")
            return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op["id"])
        if after_field in ("created_at", "updated_at"):
            after_dt = _parse_dt_any(after_val)
            if after_dt is None:
                op = _record_op("failed", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                                error_code="VALIDATION_ERROR", error_message="cursor datetime invalid.")
                return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op["id"])
        else:
            # string based cursor
            pass

    # Build membership set
    matched_item_ids = set()
    if col:
        col_id = col.get("id")
        # Join: item_collections.status='active'
        for ic in item_collections:
            if ic.get("collection_id") != col_id:
                continue
            if ic.get("status") != "active":
                continue
            # enforce same-library constraint
            if ic.get("library_id") != library_id:
                continue
            matched_item_ids.add(ic.get("item_id"))
    else:
        # No collection in this library -> empty results per read semantics
        matched_item_ids = set()

    # Filter items
    filtered = []
    for it in items:
        if it.get("library_id") != library_id:
            continue
        if it.get("id") not in matched_item_ids:
            continue
        if not include_deleted and it.get("status") != "active":
            continue
        if include_deleted:
            # still exclude if hard constraints? none; allow deleted
            pass
        else:
            if it.get("status") != "active":
                continue
        if item_type and it.get("item_type") != item_type:
            continue
        filtered.append(it)

    # Sorting
    def _skey(it):
        if sort in ("created_at", "updated_at"):
            dt = _parse_dt_any(it.get(sort))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if sort == "title":
            return (it.get("title") or "").casefold()
        if sort == "date":
            # free-form; use as lowercase string
            return (it.get("date") or "").casefold()
        return 0

    reverse = (order == "desc")
    filtered.sort(key=_skey, reverse=reverse)

    # Apply cursor after sort
    if cursor and filtered:
        def _after(it):
            if after_field in ("created_at", "updated_at"):
                dt = _parse_dt_any(it.get(after_field))
                if dt is None:
                    return False
                return dt > after_dt if not reverse else dt < after_dt
            if after_field == "title":
                v = (it.get("title") or "").casefold()
                av = (after_val or "").casefold()
                return v > av if not reverse else v < av
            if after_field == "date":
                v = (it.get("date") or "").casefold()
                av = (after_val or "").casefold()
                return v > av if not reverse else v < av
            return False
        filtered = [it for it in filtered if _after(it)]

    total = len(filtered)
    page = filtered[:limit]
    has_more = total > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        if sort in ("created_at", "updated_at"):
            dt = _parse_dt_any(last.get(sort))
            next_cursor = f"{sort}:{(dt or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)).isoformat().replace('+00:00','Z')}"
        elif sort == "title":
            next_cursor = f"title:{(last.get('title') or '')}"
        elif sort == "date":
            next_cursor = f"date:{(last.get('date') or '')}"

    op = _record_op("succeeded", {"library_id": library_id, "collection_key": collection_key, "include_deleted": include_deleted, "item_type": item_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
                    result_summary={"returned": len(page), "total_matched": total, "collection_found": bool(col)})
    return {
        "items": page,
        "collection": col if col else None,
        "paging": {"limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor},
        "operation_id": op["id"],
        "latency_ms": int((time.time() - t0) * 1000),
    }

def zotero_get_item_children(library_id, item_key, child_item_type=None, include_deleted=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
