        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

