    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    _oplog(
        library_id,
        {
            "library_id": library_id,
            "days": days,
            "item_type": item_type,
            "include_deleted": include_deleted,
            "sort": sort,
            "order": order,
            "limit": limit,
            "cursor": cursor,
        },
        "succeeded",
        result_summary={"total": total, "returned": len(page), "has_more": has_more},
    )

    return {
        "library_id": library_id,
        "items": page,
        "page": {"limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more, "total": total},
        "latency_ms": int((time.time() - _t0) * 1000),
    }

def zotero_batch_update_tags(library_id, query, add_tags=None, remove_tags=None, item_type=None, collection_id=None, limit=None, cursor=None, dry_run=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v.astimezone(datetime.timezone.utc)
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                else:
                    dt = dt.astimezone(datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[ms & 31])
            ms >>= 5
        time_part = "".join(reversed(chars))
        rand_part = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{time_part}{rand_part}"

    def _append_operation(status, params, result_summary=None, error_code=None, error_message=None, started_at=None, finished_at=None):
        ops = _load("operations.json")
        if not isinstance(ops, list):
            ops = []
        now = _iso_now()
        row = {
            "id": _new_ulid("zop"),
            "library_id": library_id if isinstance(library_id, str) else "unknown",
            "op_type": "batch_update_tags",
            "request_params_json": params if isinstance(params, dict) else {},
            "status": status,
            "result_summary_json": result_summary,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("operations.json", ops)
        return row

    def _rate_limit_allow(lib_id, max_per_minute=30):
        ops = _load("operations.json")
        if not isinstance(ops, list):
            return True, None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in ops:
            if r.get("library_id") != lib_id:
                continue
            ca = _parse_dt_any(r.get("created_at"))
            if ca and ca >= window_start:
                cnt += 1
        if cnt >= max_per_minute:
            retry_after = 60 - int((now_dt - window_start).total_seconds())
            if retry_after < 1:
                retry_after = 1
            return False, retry_after
        return True, None

    # Validate
    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                               error_code="VALIDATION_ERROR", error_message="library_id must be a zlib_* ULID.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "library_id must be a zlib_* ULID.", operation_id=op["id"])
    if not isinstance(query, str) or not query.strip():
        op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                               error_code="VALIDATION_ERROR", error_message="query must be a non-empty string.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "query must be a non-empty string.", operation_id=op["id"])

    if add_tags is None:
        add_tags = []
    if remove_tags is None:
        remove_tags = []
    if not isinstance(add_tags, list) or any(not isinstance(x, str) for x in add_tags):
        op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                               error_code="VALIDATION_ERROR", error_message="add_tags must be an array of strings.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "add_tags must be an array of strings.", operation_id=op["id"])
    if not isinstance(remove_tags, list) or any(not isinstance(x, str) for x in remove_tags):
        op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                               error_code="VALIDATION_ERROR", error_message="remove_tags must be an array of strings.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "remove_tags must be an array of strings.", operation_id=op["id"])

    if len(add_tags) == 0 and len(remove_tags) == 0:
        op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                               error_code="VALIDATION_ERROR", error_message="At least one of add_tags or remove_tags must be non-empty.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "At least one of add_tags or remove_tags must be non-empty.", operation_id=op["id"])

    if item_type is not None and item_type not in ("bibliographic", "attachment", "note", "annotation", "other"):
        op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                               error_code="VALIDATION_ERROR", error_message="item_type invalid.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "item_type must be one of: bibliographic, attachment, note, annotation, other.", operation_id=op["id"])

    if collection_id is not None:
        if not isinstance(collection_id, str) or not re.match(r"^zcol_[0-9A-HJKMNP-TV-Z]{26}$", collection_id):
            op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                                   error_code="VALIDATION_ERROR", error_message="collection_id must be a zcol_* ULID.", started_at=_iso_now(), finished_at=_iso_now())
            return _err("VALIDATION_ERROR", "collection_id must be a zcol_* ULID.", operation_id=op["id"])

    if limit is None:
        limit = 200
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                               error_code="VALIDATION_ERROR", error_message="limit out of range.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.", operation_id=op["id"])
    if cursor is not None and not isinstance(cursor, str):
        op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                               error_code="VALIDATION_ERROR", error_message="cursor must be a string.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "cursor must be a string.", operation_id=op["id"])
    if dry_run is None:
        dry_run = False
    if not isinstance(dry_run, bool):
        op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                               error_code="VALIDATION_ERROR", error_message="dry_run must be a boolean.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "dry_run must be a boolean.", operation_id=op["id"])

    libraries = _load("libraries.json")
    if not isinstance(libraries, list):
        libraries = []
    lib = next((r for r in libraries if r.get("id") == library_id), None)
    if not lib:
        op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                               error_code="NOT_FOUND", error_message="Library not found.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("NOT_FOUND", "Library not found.", operation_id=op["id"])

    ok, retry_after = _rate_limit_allow(library_id)
    if not ok:
        op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                               error_code="RATE_LIMITED", error_message=f"Too many operations created for this library in the last minute; retry after {retry_after}s.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=retry_after, operation_id=op["id"])

    # Cross-library rule: enforce only by referenced IDs. If provided collection_id exists but belongs to another library => reject.
    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []
    if collection_id is not None:
        col = next((c for c in collections if c.get("id") == collection_id), None)
        if col and col.get("library_id") != library_id:
            op = _append_operation("failed", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                                   error_code="VALIDATION_ERROR", error_message="Cross-library request rejected (collection does not belong to library).", started_at=_iso_now(), finished_at=_iso_now())
            return _err("VALIDATION_ERROR", "Cross-library request rejected (collection does not belong to library).", operation_id=op["id"])
        # If the collection_id doesn't exist at all, treat as empty match set (read-like scope computation), not validation error.
        # This mirrors search-like behavior: nothing matches => no updates.

    # Create operation in queued state first (observable dynamics)
    op = _append_operation("queued", {"library_id": library_id, "query": query, "add_tags": add_tags, "remove_tags": remove_tags, "item_type": item_type, "collection_id": collection_id, "limit": limit, "cursor": cursor, "dry_run": dry_run},
                           result_summary={"queued": True})

    # Execute synchronously (local mirror), but still follow operation transitions
    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []
    op_row = next((r for r in ops if r.get("id") == op["id"]), None)
    if not op_row:
        return _err("NOT_FOUND", "Operation not found after creation.", operation_id=op["id"])

    now = _iso_now()
    # queued -> running
    if op_row.get("status") != "queued":
        # should not happen, but don't raise
        return _err("INVALID_TRANSITION", "Operation is not in queued state.", operation_id=op_row.get("id"))
    op_row["status"] = "running"
    op_row["started_at"] = now
    op_row["updated_at"] = now
    _save("operations.json", ops)

    items = _load("items.json")
    if not isinstance(items, list):
        items = []
    item_collections = _load("item_collections.json")
    if not isinstance(item_collections, list):
        item_collections = []
    tags = _load("tags.json")
    if not isinstance(tags, list):
        tags = []

    q = query.strip().casefold()

    # cursor parsing: allow "created_at:ISO" (same as other tools); if invalid -> validation error
    after_dt = None
    if cursor:
        if ":" not in cursor:
            op_row["status"] = "failed"
            op_row["error_code"] = "VALIDATION_ERROR"
            op_row["error_message"] = "cursor is malformed."
            op_row["finished_at"] = _iso_now()
            op_row["updated_at"] = op_row["finished_at"]
            _save("operations.json", ops)
            return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op_row["id"])
        field, val = cursor.split(":", 1)
        if field != "created_at":
            op_row["status"] = "failed"
            op_row["error_code"] = "VALIDATION_ERROR"
            op_row["error_message"] = "cursor is malformed."
            op_row["finished_at"] = _iso_now()
            op_row["updated_at"] = op_row["finished_at"]
            _save("operations.json", ops)
            return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op_row["id"])
        after_dt = _parse_dt_any(val)
        if after_dt is None:
            op_row["status"] = "failed"
            op_row["error_code"] = "VALIDATION_ERROR"
            op_row["error_message"] = "cursor is malformed."
            op_row["finished_at"] = _iso_now()
            op_row["updated_at"] = op_row["finished_at"]
            _save("operations.json", ops)
            return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op_row["id"])

    # Compute search scope (MUST NOT modify items outside this computed scope)
    candidates = []
    for it in items:
        if it.get("library_id") != library_id:
            continue
        if it.get("status") != "active":
            continue
        if item_type and it.get("item_type") != item_type:
            continue
        # basic query across common fields + metadata_json serialized
        hay = " ".join([
            str(it.get("title") or ""),
            str(it.get("date") or ""),
            str(it.get("publication_title") or ""),
            str(it.get("doi") or ""),
            str(it.get("url") or ""),
            str(it.get("abstract_note") or ""),
            json.dumps(it.get("metadata_json") or {}, ensure_ascii=False),
        ]).casefold()
        if q not in hay:
            continue
        candidates.append(it)

    # Optional collection scope
    if collection_id is not None:
        # if collection doesn't exist -> empty scope
        col = next((c for c in collections if c.get("id") == collection_id and c.get("library_id") == library_id and c.get("status") == "active"), None)
        if not col:
            candidates = []
        else:
            allowed_item_ids = set()
            for ic in item_collections:
                if ic.get("library_id") != library_id:
                    continue
                if ic.get("collection_id") != collection_id:
                    continue
                if ic.get("status") != "active":
                    continue
                allowed_item_ids.add(ic.get("item_id"))
            candidates = [it for it in candidates if it.get("id") in allowed_item_ids]

    # Cursor by created_at (ascending)
    candidates.sort(key=lambda it: (_parse_dt_any(it.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)))
    if after_dt is not None:
        candidates = [it for it in candidates if (_parse_dt_any(it.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) > after_dt]

    matched = candidates[:limit]

    # Tag helpers
    def _get_or_create_tag(tag_name):
        # tag names are case-sensitive unique per library
        existing = next((t for t in tags if t.get("library_id") == library_id and t.get("name") == tag_name), None)
        if existing:
            if "item_tags" not in existing or not isinstance(existing.get("item_tags"), list):
                existing["item_tags"] = []
            return existing
        nowi = _iso_now()
        new_tag = {
            "id": _new_ulid("ztag"),
            "library_id": library_id,
            "name": tag_name,
            "color": None,
            "created_at": nowi,
            "updated_at": nowi,
            "item_tags": [],
        }
        tags.append(new_tag)
        return new_tag

    def _assign_tag(tag_row, item_id):
        its = tag_row.get("item_tags")
        if not isinstance(its, list):
            its = []
            tag_row["item_tags"] = its
        # Unique active assignment per library (implicit by tag_row)
        existing = next((x for x in its if x.get("item_id") == item_id and x.get("tag_id") == tag_row.get("id")), None)
        nowi = _iso_now()
        if existing:
            # idempotent: if removed -> activate; if active -> no-op
            if existing.get("status") == "removed":
                existing["status"] = "active"
                existing["updated_at"] = nowi
                tag_row["updated_at"] = nowi
                return True
            return False
        its.append({
            "id": _new_ulid("zit"),
            "item_id": item_id,
            "tag_id": tag_row.get("id"),
            "status": "active",
            "created_at": nowi,
            "updated_at": nowi,
        })
        tag_row["updated_at"] = nowi
        return True

    def _remove_tag(tag_row, item_id):
        its = tag_row.get("item_tags")
        if not isinstance(its, list) or not its:
            return False
        existing = next((x for x in its if x.get("item_id") == item_id and x.get("tag_id") == tag_row.get("id") and x.get("status") == "active"), None)
        if not existing:
            return False
        nowi = _iso_now()
        existing["status"] = "removed"
        existing["updated_at"] = nowi
        tag_row["updated_at"] = nowi
        return True

    # Execute updates
    changes = 0
    per_item = []
    if dry_run:
        # Report what would happen without changing
        for it in matched:
            per_item.append({"item_id": it.get("id"), "zotero_key": it.get("zotero_key"), "would_add": add_tags, "would_remove": remove_tags})
        result = {
            "operation": {k: op_row.get(k) for k in ("id", "library_id", "op_type", "status", "created_at", "started_at", "finished_at", "error_code", "error_message")},
            "dry_run": True,
            "matched_items": per_item,
            "paging": {
                "limit": limit,
                "returned": len(matched),
                "has_more": len(candidates) > limit,
                "next_cursor": (f"created_at:{(_parse_dt_any(matched[-1].get('created_at')) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)).isoformat().replace('+00:00','Z')}" if len(matched) == limit and matched else None),
            },
        }
        # running -> succeeded
        op_row["status"] = "succeeded"
        op_row["finished_at"] = _iso_now()
        op_row["updated_at"] = op_row["finished_at"]
        op_row["result_summary_json"] = {"dry_run": True, "matched": len(matched), "updated_items": 0}
        _save("operations.json", ops)
        return result

    # Apply add/remove
    # NOTE: add_tags/remove_tags are tag NAMES (strings). The audit call passed zlib_* strings; accept them as names.
    add_tag_rows = [_get_or_create_tag(n) for n in add_tags]
    remove_tag_rows = [next((t for t in tags if t.get("library_id") == library_id and t.get("name") == n), None) for n in remove_tags]

    for it in matched:
        item_id = it.get("id")
        item_change = 0
        for tr in add_tag_rows:
            if _assign_tag(tr, item_id):
                item_change += 1
        for tr in remove_tag_rows:
            if tr and _remove_tag(tr, item_id):
                item_change += 1
        changes += item_change
        per_item.append({"item_id": item_id, "zotero_key": it.get("zotero_key"), "changes": item_change})

    # Persist tag changes
    _save("tags.json", tags)

    # running -> succeeded/failed rules: NO SUCCESS WITHOUT EFFECT for mutations.
    if changes == 0:
        op_row["status"] = "failed"
        op_row["error_code"] = "NOT_FOUND"
        op_row["error_message"] = "No matching items found or no tag changes required for matched items."
        op_row["finished_at"] = _iso_now()
        op_row["updated_at"] = op_row["finished_at"]
        op_row["result_summary_json"] = {"matched": len(matched), "updated_items": 0, "changes": 0}
        _save("operations.json", ops)
        return _err("NOT_FOUND", "No matching items found or no changes to apply.", operation_id=op_row["id"])

    op_row["status"] = "succeeded"
    op_row["finished_at"] = _iso_now()
    op_row["updated_at"] = op_row["finished_at"]
    op_row["result_summary_json"] = {"matched": len(matched), "updated_items": sum(1 for x in per_item if x["changes"] > 0), "changes": changes}
    _save("operations.json", ops)

    return {
        "operation": op_row,
        "updated": {"items_changed": sum(1 for x in per_item if x["changes"] > 0), "tag_assignment_changes": changes},
        "item_results": per_item,
        "paging": {
            "limit": limit,
            "returned": len(matched),
            "has_more": len(candidates) > limit,
            "next_cursor": (f"created_at:{(_parse_dt_any(matched[-1].get('created_at')) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)).isoformat().replace('+00:00','Z')}" if len(matched) == limit and matched else None),
        },
        "latency_ms": int((time.time() - t0) * 1000),
    }

def zotero_advanced_search(library_id, criteria, match=None, item_type=None, collection_id=None, tag=None, include_deleted=None, sort=None, sort_direction=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v.astimezone(datetime.timezone.utc)
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                else:
                    dt = dt.astimezone(datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[ms & 31])
            ms >>= 5
        time_part = "".join(reversed(chars))
        rand_part = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{time_part}{rand_part}"

    def _record_op(status, params, result_summary=None, error_code=None, error_message=None):
        ops = _load("operations.json")
        if not isinstance(ops, list):
            ops = []
        now = _iso_now()
        row = {
            "id": _new_ulid("zop"),
            "library_id": library_id if isinstance(library_id, str) else "unknown",
            "op_type": "advanced_search",
            "request_params_json": params if isinstance(params, dict) else {},
            "status": status,
            "result_summary_json": result_summary,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("operations.json", ops)
        return row

    def _rate_limit_allow(lib_id, max_per_minute=60):
        ops = _load("operations.json")
        if not isinstance(ops, list):
            return True, None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in ops:
            if r.get("library_id") != lib_id:
                continue
            ca = _parse_dt_any(r.get("created_at"))
            if ca and ca >= window_start:
                cnt += 1
        if cnt >= max_per_minute:
            retry_after = 60 - int((now_dt - window_start).total_seconds())
            if retry_after < 1:
                retry_after = 1
            return False, retry_after
        return True, None

    # Validate
    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="library_id must be a zlib_* ULID.")
        return _err("VALIDATION_ERROR", "library_id must be a zlib_* ULID.", operation_id=op["id"])
    if not isinstance(criteria, list) or len(criteria) == 0:
        op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="criteria must be a non-empty array.")
        return _err("VALIDATION_ERROR", "criteria must be a non-empty array.", operation_id=op["id"])
    if match is None:
        match = "all"
    if match not in ("all", "any"):
        op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="match invalid.")
        return _err("VALIDATION_ERROR", "match must be one of: all, any.", operation_id=op["id"])
    if item_type is not None and item_type not in ("bibliographic", "attachment", "note", "annotation", "other"):
        op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="item_type invalid.")
        return _err("VALIDATION_ERROR", "item_type must be one of: bibliographic, attachment, note, annotation, other.", operation_id=op["id"])
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="include_deleted must be a boolean.")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean.", operation_id=op["id"])

    if sort is None:
        sort = "relevance"
    if sort not in ("relevance", "title", "date", "created_at", "updated_at"):
        op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="sort invalid.")
        return _err("VALIDATION_ERROR", "sort must be one of: relevance, title, date, created_at, updated_at.", operation_id=op["id"])
    if sort_direction is None:
        sort_direction = "desc"
    if sort_direction not in ("asc", "desc"):
        op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="sort_direction invalid.")
        return _err("VALIDATION_ERROR", "sort_direction must be one of: asc, desc.", operation_id=op["id"])
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="limit out of range.")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", operation_id=op["id"])
    if cursor is not None and not isinstance(cursor, str):
        op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="cursor must be a string.")
        return _err("VALIDATION_ERROR", "cursor must be a string.", operation_id=op["id"])
    if collection_id is not None:
        if not isinstance(collection_id, str) or not re.match(r"^zcol_[0-9A-HJKMNP-TV-Z]{26}$", collection_id):
            op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message="collection_id malformed.")
            return _err("VALIDATION_ERROR", "collection_id must be a zcol_* ULID.", operation_id=op["id"])

    allowed_fields = {"title", "creator", "date", "publication_title", "doi", "url", "abstract_note", "fulltext_text", "tag", "collection"}
    allowed_ops = {"contains", "equals", "starts_with", "ends_with", "exists"}

    # Validate criteria: value may be omitted/empty ONLY for 'exists'
    norm_criteria = []
    for i, c in enumerate(criteria):
        if not isinstance(c, dict):
            op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message="Each criterion must be an object.")
            return _err("VALIDATION_ERROR", "Each criterion must be an object.", operation_id=op["id"])
        field = c.get("field")
        optr = c.get("operator")
        if field not in allowed_fields:
            op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message=f"Criterion field invalid at index {i}.")
            return _err("VALIDATION_ERROR", f"Criterion field invalid at index {i}.", operation_id=op["id"])
        if optr not in allowed_ops:
            op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message=f"Criterion operator invalid at index {i}.")
            return _err("VALIDATION_ERROR", f"Criterion operator invalid at index {i}.", operation_id=op["id"])
        val_present = ("value" in c)
        val = c.get("value")
        if optr == "exists":
            # allow omitted or empty; treat value as ignored
            norm_criteria.append({"field": field, "operator": optr, "value": None})
        else:
            # accept omitted value as empty string instead of hard failing (audit defect)
            if not val_present or val is None:
                val = ""
            if not isinstance(val, str):
                op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                                error_code="VALIDATION_ERROR", error_message="Criterion value must be a string (omit only for 'exists').")
                return _err("VALIDATION_ERROR", "Criterion value must be a string (omit only for 'exists').", operation_id=op["id"])
            norm_criteria.append({"field": field, "operator": optr, "value": val})

    ok, retry_after = _rate_limit_allow(library_id)
    if not ok:
        op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="RATE_LIMITED", error_message=f"Too many operations created for this library in the last minute; retry after {retry_after}s.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=retry_after, operation_id=op["id"])

    libraries = _load("libraries.json")
    if not isinstance(libraries, list):
        libraries = []
    lib = next((r for r in libraries if r.get("id") == library_id), None)
    if not lib:
        op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="NOT_FOUND", error_message="Library not found.")
        return _err("NOT_FOUND", "Library not found.", operation_id=op["id"])

    items = _load("items.json")
    if not isinstance(items, list):
        items = []
    tags_rows = _load("tags.json")
    if not isinstance(tags_rows, list):
        tags_rows = []
    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []
    item_collections = _load("item_collections.json")
    if not isinstance(item_collections, list):
        item_collections = []

    # Validate collection_id belongs to library if provided (cross-library join rule)
    if collection_id is not None:
        col = next((c for c in collections if c.get("id") == collection_id), None)
        if col and col.get("library_id") != library_id:
            op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message="Cross-library request rejected (collection does not belong to library).")
            return _err("VALIDATION_ERROR", "Cross-library request rejected (collection does not belong to library).", operation_id=op["id"])

    # Cursor
    after_dt = None
    after_field = None
    after_val = None
    if cursor:
        if ":" not in cursor:
            op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message="cursor is malformed.")
            return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op["id"])
        after_field, after_val = cursor.split(":", 1)
        if after_field not in ("created_at", "updated_at", "date", "title"):
            op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message="cursor is malformed.")
            return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op["id"])
        if after_field in ("created_at", "updated_at"):
            after_dt = _parse_dt_any(after_val)
            if after_dt is None:
                op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                                error_code="VALIDATION_ERROR", error_message="cursor is malformed.")
                return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op["id"])

    # Precompute tag membership map if tag filter used
    tag_item_ids = None
    if tag is not None:
        # tag parameter is a tag name
        if not isinstance(tag, str):
            op = _record_op("failed", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message="tag must be a string.")
            return _err("VALIDATION_ERROR", "tag must be a string.", operation_id=op["id"])
        tr = next((t for t in tags_rows if t.get("library_id") == library_id and t.get("name") == tag), None)
        if not tr:
            tag_item_ids = set()  # no matches
        else:
            tag_item_ids = set()
            for itag in (tr.get("item_tags") or []):
                if itag.get("tag_id") != tr.get("id"):
                    continue
                if itag.get("status") != "active":
                    continue
                tag_item_ids.add(itag.get("item_id"))

    # Precompute collection membership if collection_id used
    col_item_ids = None
    if collection_id is not None:
        col_item_ids = set()
        for ic in item_collections:
            if ic.get("library_id") != library_id:
                continue
            if ic.get("collection_id") != collection_id:
                continue
            if ic.get("status") != "active":
                continue
            col_item_ids.add(ic.get("item_id"))

    # Business rule default: exclude attachments/annotations unless explicitly included by item_type
    def _default_exclude(it):
        if item_type is None and it.get("item_type") in ("attachment", "annotation"):
            return True
        return False

    def _text_for_field(it, field):
        if field == "title":
            return str(it.get("title") or "")
        if field == "creator":
            creators = it.get("creators")
            if isinstance(creators, list):
                parts = []
                for c in creators:
                    if isinstance(c, dict):
                        parts.append(" ".join([str(c.get("firstName") or ""), str(c.get("lastName") or ""), str(c.get("name") or "")]).strip())
                    else:
                        parts.append(str(c))
                return " ".join(parts)
            return ""
        if field == "date":
            return str(it.get("date") or "")
        if field == "publication_title":
            return str(it.get("publication_title") or "")
        if field == "doi":
            return str(it.get("doi") or "")
        if field == "url":
            return str(it.get("url") or "")
        if field == "abstract_note":
            return str(it.get("abstract_note") or "")
        if field == "fulltext_text":
            return str(it.get("fulltext_text") or "")
        # tag/collection handled separately
        return ""

    def _match_criterion(it, crit):
        field = crit["field"]
        optr = crit["operator"]
        val = crit["value"]
        if field == "tag":
            if optr == "exists":
                # any active tag assignment
                for t in tags_rows:
                    if t.get("library_id") != library_id:
                        continue
                    for itag in (t.get("item_tags") or []):
                        if itag.get("item_id") == it.get("id") and itag.get("tag_id") == t.get("id") and itag.get("status") == "active":
                            return True
                return False
            # otherwise value is tag name (case-sensitive)
            tr = next((t for t in tags_rows if t.get("library_id") == library_id and t.get("name") == (val or "")), None)
            if not tr:
                return False
            for itag in (tr.get("item_tags") or []):
                if itag.get("item_id") == it.get("id") and itag.get("tag_id") == tr.get("id") and itag.get("status") == "active":
                    return True
            return False

        if field == "collection":
            if optr == "exists":
                # any active membership
                for ic in item_collections:
                    if ic.get("library_id") == library_id and ic.get("item_id") == it.get("id") and ic.get("status") == "active":
                        return True
                return False
            # value may be collection zotero_key or id; accept either
            v = val or ""
            target_ids = set()
            for c in collections:
                if c.get("library_id") != library_id:
                    continue
                if c.get("id") == v or c.get("zotero_key") == v:
                    target_ids.add(c.get("id"))
            if not target_ids:
                return False
            for ic in item_collections:
                if ic.get("library_id") != library_id:
                    continue
                if ic.get("item_id") != it.get("id"):
                    continue
                if ic.get("status") != "active":
                    continue
                if ic.get("collection_id") in target_ids:
                    return True
            return False

        text = _text_for_field(it, field)
        if optr == "exists":
            return bool(text.strip())
        tv = text.casefold()
        vv = (val or "").casefold()
        if optr == "contains":
            return vv in tv
        if optr == "equals":
            return tv == vv
        if optr == "starts_with":
            return tv.startswith(vv)
        if optr == "ends_with":
            return tv.endswith(vv)
        return False

    scored = []
    for it in items:
        if it.get("library_id") != library_id:
            continue
        if not include_deleted and it.get("status") != "active":
            continue
        if item_type and it.get("item_type") != item_type:
            continue
        if _default_exclude(it):
            continue
        if collection_id is not None and col_item_ids is not None and it.get("id") not in col_item_ids:
            continue
        if tag_item_ids is not None and it.get("id") not in tag_item_ids:
            continue

        results = []
        score = 0
        for crit in norm_criteria:
            m = _match_criterion(it, crit)
            results.append(m)
            if m and crit["operator"] != "exists" and crit["value"] is not None:
                # naive relevance: count matched criteria weighted by match length
                score += 10
                # bonus if exact equals
                if crit["operator"] == "equals":
                    score += 5
        ok_match = all(results) if match == "all" else any(results)
        if not ok_match:
            continue
        scored.append((score, it))

    # Sort
    reverse = (sort_direction == "desc")
    if sort == "relevance":
        scored.sort(key=lambda x: (x[0], (_parse_dt_any(x[1].get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))), reverse=True)
        ordered = [it for _, it in scored]
    else:
        ordered = [it for _, it in scored]
        def _skey(it):
            if sort in ("created_at", "updated_at"):
                return _parse_dt_any(it.get(sort)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if sort == "title":
                return (it.get("title") or "").casefold()
            if sort == "date":
                return (it.get("date") or "").casefold()
            return 0
        ordered.sort(key=_skey, reverse=reverse)

    # Apply cursor after sorting
    if cursor and ordered:
        def _after(it):
            if after_field in ("created_at", "updated_at"):
                dt = _parse_dt_any(it.get(after_field))
                if dt is None:
                    return False
                return dt > after_dt if not reverse else dt < after_dt
            if after_field == "title":
                v = (it.get("title") or "").casefold()
                av = (after_val or "").casefold()
                return v > av if not reverse else v < av
            if after_field == "date":
                v = (it.get("date") or "").casefold()
                av = (after_val or "").casefold()
                return v > av if not reverse else v < av
            return False
        ordered = [it for it in ordered if _after(it)]

    total = len(ordered)
    page = ordered[:limit]
    has_more = total > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        if sort in ("created_at", "updated_at"):
            dt = _parse_dt_any(last.get(sort))
            next_cursor = f"{sort}:{(dt or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)).isoformat().replace('+00:00','Z')}"
        elif sort == "title":
            next_cursor = f"title:{(last.get('title') or '')}"
        elif sort == "date":
            next_cursor = f"date:{(last.get('date') or '')}"
        else:
            # relevance: cursor by updated_at
            dt = _parse_dt_any(last.get("updated_at"))
            next_cursor = f"updated_at:{(dt or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)).isoformat().replace('+00:00','Z')}"

    op = _record_op("succeeded", {"library_id": library_id, "criteria": criteria, "match": match, "item_type": item_type, "collection_id": collection_id, "tag": tag, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                    result_summary={"returned": len(page), "total_matched": total})
    return {
        "items": page,
        "paging": {"limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor},
        "operation_id": op["id"],
        "latency_ms": int((time.time() - t0) * 1000),
    }

def zotero_get_annotations(library_id, item_id=None, include_deleted=None, sort=None, sort_direction=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _record_op(lid, params, status, result_summary=None, error_code=None, error_message=None):
        ops = _load("operations.json")
        if not isinstance(ops, list):
            ops = []
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import random
        def _ulid(prefix):
            ts = int(time.time() * 1000)
            val = ts
            out = []
            for _ in range(10):
                out.append(alphabet[val & 31])
                val >>= 5
            out = "".join(reversed(out))
            rand = "".join(random.choice(alphabet) for _ in range(16))
            return f"{prefix}_{out}{rand}"
        op_id = _ulid("zop")
        row = {
            "id": op_id,
            "library_id": lid,
            "op_type": "get_annotations",
            "request_params_json": params if isinstance(params, dict) else {},
            "status": status,
            "result_summary_json": result_summary,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now if status in ("running", "succeeded", "failed", "cancelled") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("operations.json", ops)
        return row

    # Validate
    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        return _err("VALIDATION_ERROR", "library_id must be a zlib_* ULID.")
    if item_id is not None and (not isinstance(item_id, str) or not re.match(r"^zitem_[0-9A-HJKMNP-TV-Z]{26}$", item_id)):
        return _err("VALIDATION_ERROR", "item_id must be a zitem_* ULID.")
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        return _err("VALIDATION_ERROR", "include_deleted must be boolean.")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "title"):
        return _err("VALIDATION_ERROR", "sort is invalid.")
    if sort_direction is None:
        sort_direction = "desc"
    if sort_direction not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_direction is invalid.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be 1..200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    libs = _load("libraries.json")
    if not isinstance(libs, list):
        libs = []
    lib = next((l for l in libs if isinstance(l, dict) and l.get("id") == library_id), None)
    if lib is None:
        op = _record_op(library_id, {"library_id": library_id}, "failed", error_code="UNAUTHORIZED", error_message="No access to library.")
        return _err("UNAUTHORIZED", "No access to library.", operation=op)
    if lib.get("status") == "revoked":
        op = _record_op(library_id, {"library_id": library_id}, "failed", error_code="UNAUTHORIZED", error_message="Library connection revoked.")
        return _err("UNAUTHORIZED", "Library connection revoked.", operation=op)

    items = _load("items.json")
    if not isinstance(items, list):
        items = []

    # If item_id provided, it must reference an item in same library; also enforce scoping
    if item_id is not None:
        parent = next((it for it in items if isinstance(it, dict) and it.get("id") == item_id), None)
        if parent is None:
            op = _record_op(library_id, {"library_id": library_id, "item_id": item_id}, "succeeded",
                            result_summary={"total": 0, "returned": 0, "has_more": False})
            return {"annotations": [], "total": 0, "has_more": False, "next_cursor": None, "operation": op}
        if parent.get("library_id") != library_id:
            op = _record_op(library_id, {"library_id": library_id, "item_id": item_id}, "failed",
                            error_code="VALIDATION_ERROR", error_message="Cross-library request rejected.")
            return _err("VALIDATION_ERROR", "Cross-library request rejected (item does not belong to library).", operation=op)
        if not include_deleted and parent.get("status") != "active":
            # parent deleted => empty result (notes/annotations no longer visible)
            op = _record_op(library_id, {"library_id": library_id, "item_id": item_id}, "succeeded",
                            result_summary={"total": 0, "returned": 0, "has_more": False})
            return {"annotations": [], "total": 0, "has_more": False, "next_cursor": None, "operation": op}

    # Cursor decode
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            offset = obj["offset"]
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    rows = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("library_id") != library_id:
            continue
        if it.get("item_type") != "annotation":
            continue
        if it.get("annotation_json") is None:
            continue
        if not include_deleted and it.get("status") != "active":
            continue
        if item_id is not None and it.get("parent_item_id") != item_id:
            continue
        rows.append(it)

    total = len(rows)

    def _dt(s):
        if not isinstance(s, str) or not s:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    rev = (sort_direction == "desc")
    if sort == "created_at":
        rows.sort(key=lambda r: _dt(r.get("created_at")), reverse=rev)
    elif sort == "updated_at":
        rows.sort(key=lambda r: _dt(r.get("updated_at")), reverse=rev)
    elif sort == "title":
        rows.sort(key=lambda r: ((r.get("title") or "").lower(), _dt(r.get("updated_at"))), reverse=rev)

    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    op = _record_op(
        library_id,
        {
            "library_id": library_id,
            "item_id": item_id,
            "include_deleted": include_deleted,
            "sort": sort,
            "sort_direction": sort_direction,
            "limit": limit,
            "cursor": cursor,
        },
        "succeeded",
        result_summary={"total": total, "returned": len(page), "has_more": has_more},
    )

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "annotations": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "operation": op,
        "latency_ms": latency_ms,
    }

