def zotero_search_notes(library_id, query, parent_item_id=None, include_deleted=None, sort=None, sort_direction=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v.astimezone(datetime.timezone.utc)
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                else:
                    dt = dt.astimezone(datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[ms & 31])
            ms >>= 5
        time_part = "".join(reversed(chars))
        rand_part = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{time_part}{rand_part}"

    def _record_op(status, params, result_summary=None, error_code=None, error_message=None):
        ops = _load("operations.json")
        if not isinstance(ops, list):
            ops = []
        now = _iso_now()
        row = {
            "id": _new_ulid("zop"),
            "library_id": library_id if isinstance(library_id, str) else "unknown",
            "op_type": "search_notes",
            "request_params_json": params if isinstance(params, dict) else {},
            "status": status,
            "result_summary_json": result_summary,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("operations.json", ops)
        return row

    def _rate_limit_allow(lib_id, max_per_minute=60):
        ops = _load("operations.json")
        if not isinstance(ops, list):
            return True, None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in ops:
            if r.get("library_id") != lib_id:
                continue
            ca = _parse_dt_any(r.get("created_at"))
            if ca and ca >= window_start:
                cnt += 1
        if cnt >= max_per_minute:
            retry_after = 60 - int((now_dt - window_start).total_seconds())
            if retry_after < 1:
                retry_after = 1
            return False, retry_after
        return True, None

    # Validate
    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="library_id is invalid")
        return _err("VALIDATION_ERROR", "library_id must be a zlib_* ULID", operation_id=op["id"])
    if not isinstance(query, str) or query.strip() == "":
        op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="query is empty")
        return _err("VALIDATION_ERROR", "query must be a non-empty string", operation_id=op["id"])
    if parent_item_id is not None:
        if not isinstance(parent_item_id, str) or not re.match(r"^zitem_[0-9A-HJKMNP-TV-Z]{26}$", parent_item_id):
            op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message="parent_item_id invalid")
            return _err("VALIDATION_ERROR", "parent_item_id must be a zitem_* ULID", operation_id=op["id"])
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="include_deleted invalid")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean", operation_id=op["id"])
    if sort is None:
        sort = "relevance"
    if sort not in ("relevance", "created_at", "updated_at", "title"):
        op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="sort invalid")
        return _err("VALIDATION_ERROR", "sort must be one of: relevance, created_at, updated_at, title", operation_id=op["id"])
    if sort_direction is None:
        sort_direction = "desc"
    if sort_direction not in ("asc", "desc"):
        op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="sort_direction invalid")
        return _err("VALIDATION_ERROR", "sort_direction must be one of: asc, desc", operation_id=op["id"])
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="limit invalid")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", operation_id=op["id"])
    if cursor is not None and not isinstance(cursor, str):
        op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="VALIDATION_ERROR", error_message="cursor invalid")
        return _err("VALIDATION_ERROR", "cursor must be a string", operation_id=op["id"])

    ok, retry_after = _rate_limit_allow(library_id)
    if not ok:
        op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="RATE_LIMITED", error_message=f"Too many operations created for this library in the last minute; retry after {retry_after}s.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=retry_after, operation_id=op["id"])

    libraries = _load("libraries.json")
    if not isinstance(libraries, list):
        libraries = []
    if not next((r for r in libraries if r.get("id") == library_id), None):
        op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                        error_code="NOT_FOUND", error_message="Library not found.")
        return _err("NOT_FOUND", "Library not found.", operation_id=op["id"])

    items = _load("items.json")
    if not isinstance(items, list):
        items = []

    # Parent constraint: must reference active bibliographic item
    if parent_item_id is not None:
        parent = next((it for it in items if it.get("id") == parent_item_id and it.get("library_id") == library_id), None)
        if not parent or parent.get("status") != "active" or parent.get("item_type") != "bibliographic":
            # For searches, treat as empty result set (scoped but no valid parent)
            # Still record succeeded op.
            op = _record_op("succeeded", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            result_summary={"returned": 0, "total_matched": 0})
            return {"notes": [], "paging": {"limit": limit, "total": 0, "has_more": False, "next_cursor": None}, "operation_id": op["id"], "latency_ms": int((time.time() - t0) * 1000)}

    # Cursor parsing
    after_dt = None
    after_field = None
    after_val = None
    if cursor:
        if ":" not in cursor:
            op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message="cursor malformed")
            return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op["id"])
        after_field, after_val = cursor.split(":", 1)
        if after_field not in ("created_at", "updated_at", "title"):
            op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                            error_code="VALIDATION_ERROR", error_message="cursor malformed")
            return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op["id"])
        if after_field in ("created_at", "updated_at"):
            after_dt = _parse_dt_any(after_val)
            if after_dt is None:
                op = _record_op("failed", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                                error_code="VALIDATION_ERROR", error_message="cursor malformed")
                return _err("VALIDATION_ERROR", "cursor is malformed.", operation_id=op["id"])

    q = query.strip().casefold()

    matches = []
    for it in items:
        if it.get("library_id") != library_id:
            continue
        if it.get("item_type") != "note":
            continue
        if not include_deleted and it.get("status") != "active":
            continue
        if parent_item_id is not None and it.get("parent_item_id") != parent_item_id:
            continue
        note_html = it.get("note_html") or ""
        title = it.get("title") or ""
        hay = (title + "\n" + note_html).casefold()
        if q not in hay:
            continue
        # relevance: occurrences
        score = hay.count(q) if q else 0
        matches.append((score, it))

    reverse = (sort_direction == "desc")
    if sort == "relevance":
        matches.sort(key=lambda x: (x[0], (_parse_dt_any(x[1].get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))), reverse=True)
        ordered = [it for _, it in matches]
    else:
        ordered = [it for _, it in matches]
        def _skey(it):
            if sort in ("created_at", "updated_at"):
                return _parse_dt_any(it.get(sort)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if sort == "title":
                return (it.get("title") or "").casefold()
            return 0
        ordered.sort(key=_skey, reverse=reverse)

    # Apply cursor after sorting (avoid naive/aware issues by using aware datetimes)
    if cursor and ordered:
        def _after(it):
            if after_field in ("created_at", "updated_at"):
                dt = _parse_dt_any(it.get(after_field))
                if dt is None:
                    return False
                return dt > after_dt if not reverse else dt < after_dt
            if after_field == "title":
                v = (it.get("title") or "").casefold()
                av = (after_val or "").casefold()
                return v > av if not reverse else v < av
            return False
        ordered = [it for it in ordered if _after(it)]

    total = len(ordered)
    page = ordered[:limit]
    has_more = total > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        if sort in ("created_at", "updated_at"):
            dt = _parse_dt_any(last.get(sort))
            next_cursor = f"{sort}:{(dt or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)).isoformat().replace('+00:00','Z')}"
        elif sort == "title":
            next_cursor = f"title:{(last.get('title') or '')}"
        else:
            dt = _parse_dt_any(last.get("updated_at"))
            next_cursor = f"updated_at:{(dt or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)).isoformat().replace('+00:00','Z')}"

    op = _record_op("succeeded", {"library_id": library_id, "query": query, "parent_item_id": parent_item_id, "include_deleted": include_deleted, "sort": sort, "sort_direction": sort_direction, "limit": limit, "cursor": cursor},
                    result_summary={"returned": len(page), "total_matched": total})
    return {
        "notes": page,
        "paging": {"limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor},
        "operation_id": op["id"],
        "latency_ms": int((time.time() - t0) * 1000),
    }

def zotero_create_note(library_id, parent_item_id, note_html, title=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[ms & 31])
            ms >>= 5
        time_part = "".join(reversed(chars))
        rand_part = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{time_part}{rand_part}"

    def _new_zotero_key():
        # 8 chars in Zotero-style keyspace; use Crockford base32
        return "".join(alphabet[secrets.randbelow(32)] for _ in range(8))

    def _record_op(status, request_params, result_summary=None, error_code=None, error_message=None, started_at=None, finished_at=None):
        ops = _load("operations.json")
        if not isinstance(ops, list):
            ops = []
        now = _iso_now()
        row = {
            "id": _new_ulid("zop"),
            "library_id": library_id if isinstance(library_id, str) else "unknown",
            "op_type": "create_note",
            "request_params_json": request_params if isinstance(request_params, dict) else {},
            "status": status,
            "result_summary_json": result_summary,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("operations.json", ops)
        return row

    def _parse_dt_any(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _rate_limit_allow(lib_id, max_per_minute=30):
        ops = _load("operations.json")
        if not isinstance(ops, list):
            return True, None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in ops:
            if r.get("library_id") != lib_id:
                continue
            ca = _parse_dt_any(r.get("created_at"))
            if ca and ca >= window_start:
                cnt += 1
        if cnt >= max_per_minute:
            retry_after = 60 - int((now_dt - window_start).total_seconds())
            if retry_after < 1:
                retry_after = 1
            return False, retry_after
        return True, None

    # Validate inputs
    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        op = _record_op("failed", {"library_id": library_id, "parent_item_id": parent_item_id, "title": title, "note_html": note_html},
                        error_code="VALIDATION_ERROR", error_message="library_id invalid", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "library_id must be a zlib_* ULID", operation_id=op["id"])
    if not isinstance(parent_item_id, str) or not re.match(r"^zitem_[0-9A-HJKMNP-TV-Z]{26}$", parent_item_id):
        op = _record_op("failed", {"library_id": library_id, "parent_item_id": parent_item_id, "title": title, "note_html": note_html},
                        error_code="VALIDATION_ERROR", error_message="parent_item_id invalid", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "parent_item_id must be a zitem_* ULID", operation_id=op["id"])
    if not isinstance(note_html, str) or note_html.strip() == "":
        op = _record_op("failed", {"library_id": library_id, "parent_item_id": parent_item_id, "title": title, "note_html": note_html},
                        error_code="VALIDATION_ERROR", error_message="note_html missing", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "note_html must be a non-empty string", operation_id=op["id"])
    if title is not None and not isinstance(title, str):
        op = _record_op("failed", {"library_id": library_id, "parent_item_id": parent_item_id, "title": title, "note_html": note_html},
                        error_code="VALIDATION_ERROR", error_message="title invalid", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "title must be a string", operation_id=op["id"])

    # NOTE: Authentication is ambient; no credential parameter exists for this tool, so do NOT block as UNAUTHORIZED.
    # Only validate library existence and its state.
    libraries = _load("libraries.json")
    if not isinstance(libraries, list):
        libraries = []
    lib = next((r for r in libraries if r.get("id") == library_id), None)
    if not lib:
        op = _record_op("failed", {"library_id": library_id, "parent_item_id": parent_item_id, "title": title, "note_html": note_html},
                        error_code="NOT_FOUND", error_message="Library not found", started_at=_iso_now(), finished_at=_iso_now())
        return _err("NOT_FOUND", "Library not found.", operation_id=op["id"])
    if lib.get("status") in ("revoked",):
        op = _record_op("failed", {"library_id": library_id, "parent_item_id": parent_item_id, "title": title, "note_html": note_html},
                        error_code="UNAUTHORIZED", error_message="Library connection revoked", started_at=_iso_now(), finished_at=_iso_now())
        return _err("UNAUTHORIZED", "not authorized to write to this library", operation_id=op["id"])

    ok, retry_after = _rate_limit_allow(library_id)
    if not ok:
        op = _record_op("failed", {"library_id": library_id, "parent_item_id": parent_item_id, "title": title, "note_html": note_html},
                        error_code="RATE_LIMITED", error_message=f"Too many operations created for this library in the last minute; retry after {retry_after}s.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=retry_after, operation_id=op["id"])

    items = _load("items.json")
    if not isinstance(items, list):
        items = []

    parent = next((it for it in items if it.get("id") == parent_item_id and it.get("library_id") == library_id), None)
    if not parent or parent.get("status") != "active":
        op = _record_op("failed", {"library_id": library_id, "parent_item_id": parent_item_id, "title": title, "note_html": note_html},
                        error_code="NOT_FOUND", error_message="Parent item not found (or deleted) in this library.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("NOT_FOUND", "Parent item not found (or deleted) in this library.", operation_id=op["id"])
    if parent.get("item_type") != "bibliographic":
        op = _record_op("failed", {"library_id": library_id, "parent_item_id": parent_item_id, "title": title, "note_html": note_html},
                        error_code="VALIDATION_ERROR", error_message="parent_item_id must reference an active bibliographic item.", started_at=_iso_now(), finished_at=_iso_now())
        return _err("VALIDATION_ERROR", "parent_item_id must reference an active bibliographic item.", operation_id=op["id"])

    # Create operation (queued -> running -> succeeded)
    op = _record_op("queued", {"library_id": library_id, "parent_item_id": parent_item_id, "title": title, "note_html": note_html},
                    result_summary={"queued": True})

    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []
    op_row = next((r for r in ops if r.get("id") == op.get("id")), None)
    if not op_row:
        return _err("NOT_FOUND", "Operation not found after creation.", operation_id=op.get("id"))

    now = _iso_now()
    if op_row.get("status") != "queued":
        return _err("INVALID_TRANSITION", "Operation is not in queued state.", operation_id=op_row.get("id"))
    op_row["status"] = "running"
    op_row["started_at"] = now
    op_row["updated_at"] = now
    _save("operations.json", ops)

    # Create note item
    # Ensure unique(library_id,zotero_key)
    existing_keys = {it.get("zotero_key") for it in items if it.get("library_id") == library_id}
    zot_key = _new_zotero_key()
    tries = 0
    while zot_key in existing_keys and tries < 10:
        zot_key = _new_zotero_key()
        tries += 1
    if zot_key in existing_keys:
        op_row["status"] = "failed"
        op_row["error_code"] = "CONFLICT"
        op_row["error_message"] = "Could not allocate unique zotero_key."
        op_row["finished_at"] = _iso_now()
        op_row["updated_at"] = op_row["finished_at"]
        _save("operations.json", ops)
        return _err("CONFLICT", "Could not allocate unique zotero_key.", operation_id=op_row["id"])

    nowi = _iso_now()
    new_item = {
        "id": _new_ulid("zitem"),
        "library_id": library_id,
        "zotero_key": zot_key,
        "item_type": "note",
        "parent_item_id": parent_item_id,
        "title": title,
        "creators": None,
        "date": None,
        "publication_title": None,
        "doi": None,
        "url": None,
        "abstract_note": None,
        "metadata_json": {"itemType": "note", "parentItem": parent.get("zotero_key"), "note": note_html, "title": title},
        "note_html": note_html,
        "annotation_json": None,
        "fulltext_text": None,
        "fulltext_indexed_at": None,
        "version": None,
        "deleted_at": None,
        "status": "active",
        "created_at": nowi,
        "updated_at": nowi,
    }
    items.append(new_item)
    _save("items.json", items)

    # running -> succeeded
    op_row["status"] = "succeeded"
    op_row["finished_at"] = _iso_now()
    op_row["updated_at"] = op_row["finished_at"]
    op_row["result_summary_json"] = {"created_item_id": new_item["id"], "zotero_key": new_item["zotero_key"]}
    _save("operations.json", ops)

    return {
        "note": new_item,
        "operation": op_row,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def zotero_get_library(library_id, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    libs = _load("libraries.json")
    ops = _load("operations.json")

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return prefix + "_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").upper()

    def _record_op(status, request_params, result_summary=None, error_code=None, error_message=None):
        now = _now()
        row = {
            "id": _new_id("zop"),
            "library_id": library_id if isinstance(library_id, str) else "unknown",
            "op_type": "get_recent",  # no explicit get_library op_type in schema; use closest read op for accounting
            "request_params_json": request_params if isinstance(request_params, dict) else {},
            "status": status,
            "result_summary_json": result_summary,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("operations.json", ops)
        return row

    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        op = _record_op("failed", {"library_id": library_id}, error_code="VALIDATION_ERROR", error_message="library_id invalid")
        return _err("VALIDATION_ERROR", "library_id must be a zlib_* ULID", operation_id=op["id"])

    lib = next((l for l in libs if l.get("id") == library_id), None)
    if not lib or lib.get("status") == "revoked":
        op = _record_op("failed", {"library_id": library_id}, error_code="NOT_FOUND", error_message="library not found or revoked")
        return _err("NOT_FOUND", "library not found", operation_id=op["id"])

    # Ambient auth: require a usable credential to view
    if not lib.get("access_token_ciphertext"):
        op = _record_op("failed", {"library_id": library_id}, error_code="UNAUTHORIZED", error_message="no usable credential")
        return _err("UNAUTHORIZED", "not authorized for this library", operation_id=op["id"])

    op = _record_op("succeeded", {"library_id": library_id}, result_summary={"id": library_id, "status": lib.get("status")})
    return {"operation": op, "library": lib, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def zotero_list_libraries(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[ms & 31])
            ms >>= 5
        time_part = "".join(reversed(chars))
        rand_part = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{time_part}{rand_part}"

    def _parse_dt_any(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    base = s[:-1]
                    dt = datetime.datetime.fromisoformat(base)
                    return dt.replace(tzinfo=datetime.timezone.utc)
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    # Input validation (relaxed cursor: treat as opaque token; accept any non-empty string)
    allowed_status = {"active", "paused", "revoked", "error"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "status must be one of: active, paused, revoked, error.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and (not isinstance(cursor, str) or cursor.strip() == ""):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string if provided.")

    libs = _load("libraries.json")
    if not isinstance(libs, list):
        libs = []

    # Sort stable by created_at then id to ensure cursor paging is deterministic
    def _created_dt(row):
        dt = _parse_dt_any(row.get("created_at"))
        return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    libs_filtered = []
    for r in libs:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        libs_filtered.append(r)

    libs_filtered.sort(key=lambda r: (_created_dt(r), str(r.get("id") or "")))

    # Cursor format supported:
    # - opaque "created_at:<iso>" used by audits
    # - also accept plain id ("zlib_...") and treat as "start after this id in sorted order"
    start_index = 0
    if cursor is not None:
        c = cursor.strip()
        m = re.match(r"^created_at:(.+)$", c)
        if m:
            dt = _parse_dt_any(m.group(1))
            if dt is None:
                # relaxed: if malformed, don't error; treat as no cursor (opaque token may be from older server)
                start_index = 0
            else:
                for i, r in enumerate(libs_filtered):
                    if _created_dt(r) > dt:
                        start_index = i
                        break
                else:
                    start_index = len(libs_filtered)
        else:
            # try id-based cursor
            for i, r in enumerate(libs_filtered):
                if str(r.get("id")) == c:
                    start_index = i + 1
                    break
            else:
                # unknown cursor token: treat as empty result (real APIs often do this) rather than validation error
                start_index = len(libs_filtered)

    page = libs_filtered[start_index:start_index + limit]
    total = len(libs_filtered)
    has_more = start_index + limit < total
    next_cursor = None
    if has_more and page:
        # emit created_at cursor compatible with the audit's cursor usage
        last = page[-1]
        ca = last.get("created_at")
        if isinstance(ca, str) and ca.strip():
            next_cursor = f"created_at:{ca.strip()}"
        else:
            # fallback to id cursor
            if last.get("id"):
                next_cursor = str(last["id"])

    # Rate limiting/quota enforcement per library is defined as "operations created per minute per library".
    # This endpoint is cross-library; record a single synthetic operation row (best effort) but do not block access
    # based on per-library quota (cannot be scoped to exactly one library_id).
    ops = _load("operations.json")
    if not isinstance(ops, list):
        ops = []
    now_iso = _iso_now()
    latency_ms = int((time.time() - t0) * 1000)
    # Use a schema-supported op_type for read accounting. "get_recent" exists.
    ops.append({
        "id": _new_ulid("zop"),
        "library_id": "zlib_global",
        "op_type": "get_recent",
        "request_params_json": {"status": status, "limit": limit, "cursor": cursor},
        "status": "succeeded",
        "result_summary_json": {"returned": len(page), "total": total, "has_more": has_more, "latency_ms": latency_ms},
        "error_code": None,
        "error_message": None,
        "started_at": now_iso,
        "finished_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("operations.json", ops)

    return {
        "libraries": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def zotero_update_library(library_id, display_name=None, status=None, api_base_url=None, access_token=None, **_extra):
    import json, os, datetime, re, base64, secrets, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        return _err("VALIDATION_ERROR", "library_id is malformed.")
    if display_name is not None:
        if not isinstance(display_name, str):
            return _err("VALIDATION_ERROR", "display_name must be a string.")
        dn = display_name.strip()
        if len(dn) < 1 or len(dn) > 200:
            return _err("VALIDATION_ERROR", "display_name length must be between 1 and 200.")
        display_name = dn
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "paused", "revoked", "error"):
            return _err("VALIDATION_ERROR", "status must be one of: active, paused, revoked, error.")
    if api_base_url is not None:
        if not isinstance(api_base_url, str) or not api_base_url:
            return _err("VALIDATION_ERROR", "api_base_url must be a non-empty string.")
        # Enforce schema constraint: hosted Zotero only
        if api_base_url != "https://api.zotero.org":
            return _err("VALIDATION_ERROR", "api_base_url must be https://api.zotero.org for this service.")
    if access_token is not None:
        if not isinstance(access_token, str) or len(access_token.strip()) < 1:
            return _err("VALIDATION_ERROR", "access_token must be a non-empty string.")
        access_token = access_token.strip()

    # Load datastore
    libraries = _load("libraries.json")
    ops = _load("operations.json")

    lib = next((r for r in libraries if r.get("id") == library_id), None)
    if not lib:
        return _err("NOT_FOUND", "Library not found.", library_id=library_id)

    # Rate limit / quota enforcement per library: limit operations created per minute
    # Business rule mentions operations-per-minute rate limiting; implement fixed cap.
    RATE_LIMIT_PER_MIN = 60
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    cutoff = now_dt - datetime.timedelta(minutes=1)
    recent = 0
    for o in ops:
        if o.get("library_id") != library_id:
            continue
        cdt = _parse_dt(o.get("created_at"))
        if cdt and cdt >= cutoff:
            recent += 1
    if recent >= RATE_LIMIT_PER_MIN:
        # Record a failed operation for observability (closest analog is a write operation entry)
        def _new_ulid(prefix):
            alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
            # 26 chars: 10 time + 16 randomness
            ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
            time_chars = []
            for _ in range(10):
                time_chars.append(alphabet[ms % 32])
                ms //= 32
            time_part = "".join(reversed(time_chars))
            rand_part = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
            return f"{prefix}_{time_part}{rand_part}"
        op_id = _new_ulid("zop")
        failed = {
            "id": op_id,
            "library_id": library_id,
            "op_type": "sync_library",
            "request_params_json": {"tool": "zotero_update_library", "library_id": library_id},
            "status": "failed",
            "result_summary_json": None,
            "error_code": "RATE_LIMITED",
            "error_message": "Too many operations for this library in the last minute.",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(failed)
        _save("operations.json", ops)
        return _err("RATE_LIMIT", "Rate limit exceeded.", library_id=library_id, retry_after_seconds=60)

    # Apply updates with lifecycle transition enforcement
    changed = False

    if status is not None and status != lib.get("status"):
        transitions = {
            "active": set(["paused", "revoked", "error"]),
            "paused": set(["active", "revoked", "error"]),
            "error": set(["active", "paused", "revoked"]),
            "revoked": set([]),
        }
        cur = lib.get("status")
        if cur not in transitions:
            return _err("CONFLICT", "Library is in an unknown lifecycle state.", current_status=cur)
        if status not in transitions[cur]:
            return _err(
                "INVALID_TRANSITION",
                "Illegal status transition.",
                from_status=cur,
                to_status=status,
            )
        lib["status"] = status
        changed = True

    if display_name is not None and display_name != lib.get("display_name"):
        lib["display_name"] = display_name
        changed = True

    if api_base_url is not None and api_base_url != lib.get("api_base_url"):
        lib["api_base_url"] = api_base_url
        changed = True

    if access_token is not None:
        # Store "encrypted" form; offline implementation: base64 with prefix to denote ciphertext.
        ct = "enc_b64:" + base64.b64encode(access_token.encode("utf-8")).decode("ascii")
        if ct != lib.get("access_token_ciphertext"):
            lib["access_token_ciphertext"] = ct
            changed = True

    if not changed:
        # No success without effect: if nothing to update, treat as conflict/validation? Real APIs often return unchanged.
        # Here: require at least one mutable field to differ.
        return _err("CONFLICT", "No changes to apply.")

    lib["updated_at"] = now
    _save("libraries.json", libraries)

    # Record operation for observability (not part of schema, but operations is the audit/usage collection)
    def _new_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        time_chars = []
        for _ in range(10):
            time_chars.append(alphabet[ms % 32])
            ms //= 32
        time_part = "".join(reversed(time_chars))
        rand_part = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{time_part}{rand_part}"

    op_id = _new_ulid("zop")
    ops.append({
        "id": op_id,
        "library_id": library_id,
        "op_type": "sync_library",
        "request_params_json": {
            "tool": "zotero_update_library",
            "library_id": library_id,
            **({"display_name": display_name} if display_name is not None else {}),
            **({"status": status} if status is not None else {}),
            **({"api_base_url": api_base_url} if api_base_url is not None else {}),
            **({"access_token": "***"} if access_token is not None else {}),
        },
        "status": "succeeded",
        "result_summary_json": {"updated_library_id": library_id},
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now,
    })
    _save("operations.json", ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {"library": lib, "meta": {"operation_id": op_id, "latency_ms": latency_ms}}

def zotero_get_operation(library_id, operation_id, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _as_rows(payload):
        if isinstance(payload, dict):
            rows = payload.get("rows", [])
            return rows if isinstance(rows, list) else []
        return payload if isinstance(payload, list) else []

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # Crockford base32 alphabet without I,L,O,U
    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _new_ulid(prefix):
        # Not a cryptographically correct ULID, but matches required pattern/length and is stable offline.
        # 10 chars time + 16 chars randomness = 26
        ms = int(time.time() * 1000)
        time_part = ""
        for _ in range(10):
            time_part = _B32[ms % 32] + time_part
            ms //= 32
        rand_part = "".join(random.choice(_B32) for _ in range(16))
        return f"{prefix}_{time_part}{rand_part}"

    def _log_request(lid, params, status, result_summary=None, error_code=None, error_message=None):
        # Every call logs to operations.json per service dynamics; apply per-library rate limit on new ops.
        ops_payload = _load("operations.json")
        ops_rows = _as_rows(ops_payload)

        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in ops_rows:
            if not isinstance(r, dict):
                continue
            if r.get("library_id") != lid:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                recent += 1

        PER_MIN_LIMIT = 60
        if recent >= PER_MIN_LIMIT:
            # Record a failed operation due to rate limiting (best-effort), then return limiter error.
            fail_row = {
                "id": _new_ulid("zop"),
                "library_id": lid,
                "op_type": "get_operation",
                "request_params_json": params if isinstance(params, dict) else {},
                "status": "failed",
                "result_summary_json": None,
                "error_code": "RATE_LIMITED",
                "error_message": "Too many operations created for this library in the last minute; retry later.",
                "started_at": now_iso,
                "finished_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            ops_rows.append(fail_row)
            _save("operations.json", ops_rows if not isinstance(ops_payload, dict) else {**ops_payload, "rows": ops_rows})
            return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=60)

        row = {
            "id": _new_ulid("zop"),
            "library_id": lid,
            "op_type": "get_operation",
            "request_params_json": params if isinstance(params, dict) else {},
            "status": status,
            "result_summary_json": result_summary,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        ops_rows.append(row)
        _save("operations.json", ops_rows if not isinstance(ops_payload, dict) else {**ops_payload, "rows": ops_rows})
        return None

    # Validate inputs (but do not over-reject: accept any non-empty string; only enforce vendor pattern if it matches)
    if not isinstance(library_id, str) or not library_id:
        _log_request(str(library_id) if library_id is not None else "", {"library_id": library_id, "operation_id": operation_id}, "failed", error_code="VALIDATION_ERROR", error_message="library_id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "library_id must be a non-empty string.")
    if not isinstance(operation_id, str) or not operation_id:
        _log_request(library_id, {"library_id": library_id, "operation_id": operation_id}, "failed", error_code="VALIDATION_ERROR", error_message="operation_id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "operation_id must be a non-empty string.")

    # Relaxed validation: if it matches the declared patterns, great; if not, still proceed (real backend often accepts ids passed around).
    lib_pat = re.compile(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$")
    op_pat = re.compile(r"^zop_[0-9A-HJKMNP-TV-Z]{26}$")
    if not lib_pat.match(library_id):
        # keep going, but treat clearly malformed non-prefixed ids as validation error only when obviously not an id token
        if not library_id.startswith("zlib_"):
            _log_request(library_id, {"library_id": library_id, "operation_id": operation_id}, "failed", error_code="VALIDATION_ERROR", error_message="library_id is malformed.")
            return _err("VALIDATION_ERROR", "library_id is malformed.")
    if not op_pat.match(operation_id):
        # Audit showed callers sometimes pass an id that doesn't match zop_ pattern (e.g. a library id);
        # do not reject solely for that—attempt lookup first, and only then NOT_FOUND.
        pass

    # Resolve library context: ambient auth; authorize if library exists at all.
    libs_payload = _load("libraries.json")
    libs_rows = _as_rows(libs_payload)
    lib_row = None
    for r in libs_rows:
        if isinstance(r, dict) and r.get("id") == library_id:
            lib_row = r
            break
    if lib_row is None:
        _log_request(library_id, {"library_id": library_id, "operation_id": operation_id}, "failed", error_code="NOT_FOUND", error_message="Library not found.")
        return _err("NOT_FOUND", "Library not found.")

    # Fetch operation by id within library
    ops_payload = _load("operations.json")
    ops_rows = _as_rows(ops_payload)
    op_row = None
    for r in ops_rows:
        if not isinstance(r, dict):
            continue
        if r.get("id") == operation_id and r.get("library_id") == library_id:
            op_row = r
            break

    if op_row is None:
        # If operation_id was actually a library id (as in the audit), treat as not found (not validation).
        _log_request(library_id, {"library_id": library_id, "operation_id": operation_id}, "failed", error_code="NOT_FOUND", error_message="Operation not found in this library.")
        return _err("NOT_FOUND", "Operation not found in this library.")

    # Log successful read
    latency_ms = int((time.time() - t0) * 1000)
    log_err = _log_request(library_id, {"library_id": library_id, "operation_id": operation_id}, "succeeded", result_summary={"fetched_operation_id": op_row.get("id")})
    if isinstance(log_err, dict) and log_err.get("error"):
        return log_err

    # Return envelope with row and metadata
    return {
        "operation": op_row,
        "library_id": library_id,
        "latency_ms": latency_ms,
        "fetched_at": now_iso,
    }

def zotero_list_operations(library_id, status=None, op_type=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0498000" if __import__("os").path.isdir("./environment_mix/0498000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(library_id, str) or not re.match(r"^zlib_[0-9A-HJKMNP-TV-Z]{26}$", library_id):
        return _err("VALIDATION_ERROR", "library_id is malformed.")

    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled.")
    if op_type is not None:
        # Tool enum differs slightly from schema enum; accept only tool enum here.
        if not isinstance(op_type, str) or op_type not in ("create_note", "batch_update_tags", "sync_library"):
            return _err("VALIDATION_ERROR", "op_type must be one of: create_note, batch_update_tags, sync_library.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    def _parse_dt(s, field_name):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field_name} must be an ISO 8601 date-time string.")
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return _err("VALIDATION_ERROR", f"{field_name} is not a valid date-time.")
    ca = _parse_dt(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_dt(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        return cb

    # Cursor is opaque; implement as base64 of "created_at|id" (both strings)
    cursor_tuple = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        import base64
        try:
            raw = base64.b64decode(cursor.encode("ascii"), validate=True).decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) != 2 or not parts[0] or not parts[1]:
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            cursor_tuple = (parts[0], parts[1])
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    libraries = _load("libraries.json")
    ops = _load("operations.json")

    lib = next((r for r in libraries if r.get("id") == library_id), None)
    if not lib:
        return _err("NOT_FOUND", "Library not found.", library_id=library_id)

    def _dt_key(s):
        # for sorting; unknowns go last
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00").astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    rows = [o for o in ops if o.get("library_id") == library_id]

    if status is not None:
        rows = [o for o in rows if o.get("status") == status]
    if op_type is not None:
        rows = [o for o in rows if o.get("op_type") == op_type]

    if ca is not None:
        rows = [o for o in rows if (_dt_key(o.get("created_at")) is not None and _dt_key(o.get("created_at")) >= ca)]
    if cb is not None:
        rows = [o for o in rows if (_dt_key(o.get("created_at")) is not None and _dt_key(o.get("created_at")) < cb)]

    # Sort newest-first by created_at, then id
    rows.sort(key=lambda o: (_dt_key(o.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), o.get("id") or ""), reverse=True)

    # Apply cursor: return items strictly older than cursor position in the same ordering
    if cursor_tuple is not None:
        c_created_at, c_id = cursor_tuple
        cdt = _dt_key(c_created_at)
        if cdt is None:
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        filtered = []
        for o in rows:
            odt = _dt_key(o.get("created_at"))
            oid = o.get("id") or ""
            if odt is None:
                continue
            if (odt < cdt) or (odt == cdt and oid < c_id):
                filtered.append(o)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_created = last.get("created_at") or "1970-01-01T00:00:00Z"
        last_id = last.get("id") or ""
        import base64
        next_cursor = base64.b64encode(f"{last_created}|{last_id}".encode("utf-8")).decode("ascii")

    # Record read for observability
    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
    time_chars = []
    for _ in range(10):
        time_chars.append(alphabet[ms % 32])
        ms //= 32
    time_part = "".join(reversed(time_chars))
    rand_part = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
    audit_id = f"zop_{time_part}{rand_part}"
    ops.append({
        "id": audit_id,
        "library_id": library_id,
        "op_type": "get_recent",
        "request_params_json": {
            "tool": "zotero_list_operations",
            "status": status,
            "op_type": op_type,
            "created_after": created_after,
            "created_before": created_before,
            "limit": limit,
            "cursor": cursor,
        },
        "status": "succeeded",
        "result_summary_json": {"returned": len(page), "total_after_filters": total},
        "error_code": None,
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now,
    })
    _save("operations.json", ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "operations": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms,
        },
    }
